css:
:root {
  --primary: #2fbf71;
  --primary-hover: #1e9d5a;
  --bg: #0f2319;
  --bg-alt: #123222;
  --card-bg: #193928;
  --text: #e7f4ea;
  --text-secondary: #b4d3c1;
  --border: #2c5d3e;
  --accent-lime: #b0f55f;
  --accent-gold: #f2c14e;
  --shadow-canopy: 0 18px 40px rgba(4, 23, 12, 0.45);
}

body {
  background: radial-gradient(closest-side at 20% 20%, rgba(47,191,113,0.15), transparent 55%),
              radial-gradient(closest-corner at 80% 0%, rgba(176,245,95,0.12), transparent 45%),
              linear-gradient(160deg, #0c1b13 0%, #0f261a 35%, #123322 100%);
  color: var(--text);
}

.header {
  background: linear-gradient(135deg, rgba(47,191,113,0.35) 0%, rgba(30,157,90,0.22) 100%),
              url('data:image/svg+xml,%3Csvg width="160" height="160" xmlns="http://www.w3.org/2000/svg"%3E%3Cpath d="M0 80 C40 60 80 120 160 70" stroke="%231e9d5a" stroke-width="18" fill="none" opacity="0.35"/%3E%3C/svg%3E');
  border-bottom: 3px solid var(--primary);
  box-shadow: 0 10px 30px rgba(0,0,0,0.35);
}

.brand {
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent-lime);
  text-shadow: 0 0 12px rgba(176,245,95,0.4), 0 0 32px rgba(47,191,113,0.25);
}

.card {
  background: linear-gradient(180deg, rgba(25,57,40,0.92) 0%, rgba(17,37,27,0.88) 100%);
  border: 1px solid rgba(176,245,95,0.24);
  border-radius: 16px;
  box-shadow: var(--shadow-canopy);
  position: relative;
  overflow: hidden;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 20% 18%, rgba(176,245,95,0.12) 0%, transparent 40%),
              radial-gradient(circle at 78% 16%, rgba(47,191,113,0.10) 0%, transparent 32%);
  pointer-events: none;
}

.card::after {
  content: "";
  position: absolute;
  width: 180px;
  height: 180px;
  bottom: -90px;
  right: -60px;
  background: radial-gradient(circle, rgba(176,245,95,0.15) 0%, transparent 65%);
  filter: blur(8px);
  opacity: 0.65;
}

.card:hover {
  transform: translateY(-6px) scale(1.01);
  border-color: rgba(242,193,78,0.5);
  box-shadow: 0 24px 44px rgba(0,0,0,0.45);
}

.card .card-title {
  color: #f8ffe8;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.card .card-body {
  color: var(--text-secondary);
  line-height: 1.75;
}

.card .tag,
.card .label {
  background: linear-gradient(90deg, rgba(47,191,113,0.9) 0%, rgba(30,157,90,0.9) 60%, rgba(242,193,78,0.8) 100%);
  border: 1px solid rgba(176,245,95,0.5);
  color: #0d1a12;
  border-radius: 999px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.18), 0 6px 14px rgba(0,0,0,0.35);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sidebar,
.panel,
.modal,
.popover {
  background: rgba(13, 29, 21, 0.9);
  border: 1px solid rgba(47,191,113,0.35);
  box-shadow: 0 16px 30px rgba(0,0,0,0.5);
  backdrop-filter: blur(6px);
}

.list-item,
.menu-item,
.dropdown-item {
  background: rgba(19, 45, 32, 0.88);
  border-radius: 12px;
  border: 1px solid rgba(176,245,95,0.25);
  transition: transform 0.15s ease, background 0.18s ease;
}

.list-item:hover,
.menu-item:hover,
.dropdown-item:hover {
  transform: translateX(4px);
  background: rgba(30, 69, 48, 0.9);
}

.progress,
.timeline::before,
.board::before {
  background: linear-gradient(90deg, rgba(47,191,113,0.35), rgba(176,245,95,0.12), rgba(47,191,113,0.35));
}

.floating-ribbon {
  background: linear-gradient(180deg, rgba(176,245,95,0.95) 0%, rgba(47,191,113,0.95) 70%);
  color: #0e1c14;
  box-shadow: var(--shadow-canopy);
}
